-- Base data every environment needs: providers, admin, app modules, demo logins.
-- Patients come from load_patients.sql (Synthea demographics); everything clinical
-- is generated by the seed_*.sql scripts. See README for the run order.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- ============ PEOPLE ============
INSERT INTO users (email, display_name, title, specialty, role) VALUES
  ('sarah.jenkins@example.com', 'Dr. Sarah Jenkins', 'Clinical Psychologist', 'Anxiety & Mood Disorders',          'Provider'),
  ('robert.miller@example.com', 'Dr. Robert Miller', 'Psychiatrist',          'Depression & Mood',                  'Provider'),
  ('amanda.chen@example.com',   'Dr. Amanda Chen',   'Clinical Psychologist', 'Trauma & PTSD',                      'Provider'),
  ('david.ross@example.com',    'Dr. David Ross',    'Art Therapist',         'Expressive & Creative Arts Therapy', 'Provider'),
  ('admin@example.com',         'Admin User',        'Administrator',         '',                                   'Admin')
ON CONFLICT (email) DO NOTHING;

